real xmin = -3.5240093012803015, xmax = 11.281247367575242, ymin = -2.6545617728840334, ymax = 7.1662584841234755;  /* image dimensions */


draw((0,0)--(5,0)--(5,3)--(7,3)--(7,4)--(4,4)--(4,1)--(0,1)--cycle, linewidth(2)); 
 /* draw figures */
draw((0,0)--(5,0), linewidth(2)); 
draw((5,0)--(5,3), linewidth(2)); 
draw((5,3)--(7,3), linewidth(2)); 
draw((7,3)--(7,4), linewidth(2)); 
draw((7,4)--(4,4), linewidth(2)); 
draw((4,4)--(4,1), linewidth(2)); 
draw((4,1)--(0,1), linewidth(2)); 
draw((0,1)--(0,0), linewidth(2)); 
draw((6,3)--(6,4), linewidth(2)); 
draw((5,4)--(5,3), linewidth(2)); 
draw((5,3)--(4,3), linewidth(2)); 
draw((4,2)--(5,2), linewidth(2)); 
draw((5,1)--(4,1), linewidth(2)); 
draw((4,0)--(4,1), linewidth(2)); 
draw((3,0)--(3,1), linewidth(2)); 
draw((2,0)--(2,1), linewidth(2)); 
draw((1,1)--(1,0), linewidth(2)); 
 /* dots and labels */ 
clip((xmin,ymin)--(xmin,ymax)--(xmax,ymax)--(xmax,ymin)--cycle); 
 /* end of picture */
[/asy]

Triangle  $ABC$  has right angle at  $B$ , and contains a point  $P$  for which  $PA = 10$ ,  $PB = 6$ , and  $\angle APB = \angle BPC = \angle CPA$ .  Find  $PC$ .

[asy]
pair A=(0,5), B=origin, C=(12,0), D=rotate(-60)*C, F=rotate(60)*A, P=intersectionpoint(A--D, C--F);
draw(A--P--B--A--C--B^^C--P);
dot(A^^B^^C^^P);
pair point=P;
label(" $A$ ", A, dir(point--A));
label(" $B$ ", B, dir(point--B));
label(" $C$ ", C, dir(point--C));
label(" $P$ ", P, NE);[/asy]

The diagram show  $28$  lattice points, each one unit from its nearest neighbors. Segment  $AB$  meets segment  $CD$  at  $E$ . Find the length of segment  $AE$ .

[asy]
