seg1=(6,0)--(0,3);
seg2=(2,0)--(4,2);
dot((0,0));
dot((1,0));
fill(circle((2,0),0.1),black);
dot((3,0));
dot((4,0));
dot((5,0));
fill(circle((6,0),0.1),black);
dot((0,1));
dot((1,1));
